<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- creature modal body from legacy snapshot */
  import { onDestroy } from 'svelte';
  import {
    setCreatureModalShow,
    setCreatureModalClose,
  } from '../bridge/creatureModalBridge.js';
  import { publishModalOpened } from '../bus/publishHooks.js';

  let visible = $state(false);
  let contentHtml = $state('');

  function show(html: string) {
    const modal = document.getElementById('creatureModal');
    const opening = !modal?.classList.contains('show');
    contentHtml = html;
    visible = true;
    modal?.classList.add('show');
    if (opening) publishModalOpened('creatureModal');
  }

  function close() {
    visible = false;
    contentHtml = '';
    document.getElementById('creatureModal')?.classList.remove('show');
  }

  setCreatureModalShow(show);
  setCreatureModalClose(close);
  onDestroy(() => {
    setCreatureModalShow(() => {});
    setCreatureModalClose(() => {});
  });
</script>

<div class="stats-content" id="creatureModalContent" data-action="stopPropagation" data-action-stop>
  {#if visible && contentHtml}
    {@html contentHtml}
  {/if}
</div>
